'use client';

import { useTranslations } from 'next-intl';
import { usePathname } from '@/i18n/routing';
import { Link } from '@/i18n/routing';
import { useState } from 'react';
import { Menu, X } from 'iconoir-react';

export default function Navigation() {
  const t = useTranslations('common');
  const pathname = usePathname();
  const [isOpen, setIsOpen] = useState(false);

  const locale = pathname.split('/')[1] || 'en';

  const toggleMenu = () => setIsOpen(!isOpen);

  const navLinks = [
    { href: `/${locale}#about`, label: t('about') },
    { href: `/${locale}#experience`, label: t('experience') },
    { href: `/${locale}#projects`, label: t('projects') },
    { href: `/${locale}#skills`, label: t('skills') },
    { href: `/${locale}#contact`, label: t('contact') },
  ];

  return (
    <nav className="fixed top-0 left-0 right-0 z-50 bg-white/80 dark:bg-gray-900/80 backdrop-blur-md border-b border-gray-200 dark:border-gray-800">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex justify-between items-center h-16">
          <Link href={`/${locale}`} className="text-xl font-bold text-gray-900 dark:text-white">
            MC
          </Link>

          {/* Desktop Navigation */}
          <div className="hidden md:flex items-center space-x-8">
            {navLinks.map((link) => (
              <Link
                key={link.href}
                href={link.href}
                className="text-gray-700 dark:text-gray-300 hover:text-gray-900 dark:hover:text-white transition-colors"
              >
                {link.label}
              </Link>
            ))}
            <div className="flex items-center space-x-2">
              <Link
                href="/en"
                className={`px-2 py-1 rounded ${locale === 'en' ? 'bg-gray-900 text-white dark:bg-white dark:text-gray-900' : 'text-gray-700 dark:text-gray-300'}`}
              >
                EN
              </Link>
              <Link
                href="/fr"
                className={`px-2 py-1 rounded ${locale === 'fr' ? 'bg-gray-900 text-white dark:bg-white dark:text-gray-900' : 'text-gray-700 dark:text-gray-300'}`}
              >
                FR
              </Link>
            </div>
          </div>

          {/* Mobile Menu Button */}
          <button
            className="md:hidden text-gray-700 dark:text-gray-300"
            onClick={toggleMenu}
            aria-label="Toggle menu"
          >
            {isOpen ? <X className="w-6 h-6" /> : <Menu className="w-6 h-6" />}
          </button>
        </div>

        {/* Mobile Navigation */}
        {isOpen && (
          <div className="md:hidden py-4 space-y-4">
            {navLinks.map((link) => (
              <Link
                key={link.href}
                href={link.href}
                className="block text-gray-700 dark:text-gray-300 hover:text-gray-900 dark:hover:text-white transition-colors"
                onClick={() => setIsOpen(false)}
              >
                {link.label}
              </Link>
            ))}
            <div className="flex items-center space-x-2 pt-4 border-t border-gray-200 dark:border-gray-800">
              <Link
                href="/en"
                className={`px-2 py-1 rounded ${locale === 'en' ? 'bg-gray-900 text-white dark:bg-white dark:text-gray-900' : 'text-gray-700 dark:text-gray-300'}`}
                onClick={() => setIsOpen(false)}
              >
                EN
              </Link>
              <Link
                href="/fr"
                className={`px-2 py-1 rounded ${locale === 'fr' ? 'bg-gray-900 text-white dark:bg-white dark:text-gray-900' : 'text-gray-700 dark:text-gray-300'}`}
                onClick={() => setIsOpen(false)}
              >
                FR
              </Link>
            </div>
          </div>
        )}
      </div>
    </nav>
  );
}

